js=jspdf.read_text()
import_line=js.split(';',1)[0]+';'
# actual first statement includes helper vars then import, so replace exact import token instead
import re
m=re.search(r'import\{_ as ([A-Za-z_$][\w$]*)\}from"\.\/index-[^"]+\.js";',js)
if not m: raise SystemExit('jspdf helper import not found')
helper=m.group(1)
js=js[:m.start()]+f'const {helper}=(fn)=>fn();'+js[m.end():]
standalone=root/'assets'/'jspdf.standalone-v1453.js'
standalone.write_text(js)
